'use strict';

var nativeSetPrototypeOf = Object.setPrototypeOf;

function assertObject(value, name) {
  var type = typeof value;
  if (value === null || (type !== 'object' && type !== 'function')) {
    throw new TypeError(name + ' must be an object or a function');
  }
}

function assertPrototype(proto) {
  var type = typeof proto;
  if (proto !== null && type !== 'object' && type !== 'function') {
    throw new TypeError('prototype must be an object or null');
  }
}

function setViaNative(obj, proto) {
  nativeSetPrototypeOf(obj, proto);
  return obj;
}

function setViaProto(obj, proto) {
  obj.__proto__ = proto;
  return obj;
}

function setViaCopy(obj, proto) {
  var result = Object.create(proto);
  Object.getOwnPropertyNames(obj).forEach(function (key) {
    Object.defineProperty(result, key, Object.getOwnPropertyDescriptor(obj, key));
  });
  return result;
}

var supportsProto = (function () {
  if (!('__proto__' in {})) {
    return false;
  }
  try {
    var probe = {};
    probe.__proto__ = { marker: true };
    return probe.marker === true;
  } catch (err) {
    return false;
  }
})();

var setPrototypeOf;

if (nativeSetPrototypeOf) {
  setPrototypeOf = setViaNative;
} else if (supportsProto) {
  setPrototypeOf = setViaProto;
} else {
  setPrototypeOf = setViaCopy;
}

module.exports = function setPrototypeOf(obj, proto) {
  assertObject(obj, 'obj');
  assertPrototype(proto);
  return setPrototypeOf(obj, proto);
};

module.exports.setPrototypeOf = module.exports;

declare function setPrototypeOf<T extends object>(
  obj: T,
  proto: object | null
): T;

declare namespace setPrototypeOf {
  export { setPrototypeOf };
}

export = setPrototypeOf;

'use strict';

var test = require('node:test');
var assert = require('node:assert');
var setPrototypeOf = require('./index.js');

test('sets the prototype of an object', function () {
  var proto = { hello: function () { return 'world'; } };
  var obj = {};
  var returned = setPrototypeOf(obj, proto);
  assert.strictEqual(returned, obj);
  assert.strictEqual(Object.getPrototypeOf(obj), proto);
  assert.strictEqual(obj.hello(), 'world');
});

test('supports a null prototype', function () {
  var obj = { a: 1 };
  setPrototypeOf(obj, null);
  assert.strictEqual(Object.getPrototypeOf(obj), null);
  assert.strictEqual(obj.a, 1);
});

test('sets the prototype of a function', function () {
  function target() {}
  var proto = { tag: 'fn' };
  setPrototypeOf(target, proto);
  assert.strictEqual(Object.getPrototypeOf(target), proto);
});

test('keeps own properties intact', function () {
  var obj = { b: 2 };
  Object.defineProperty(obj, 'hidden', { value: 3, enumerable: false });
  setPrototypeOf(obj, { c: 4 });
  assert.strictEqual(obj.b, 2);
  assert.strictEqual(obj.hidden, 3);
  assert.strictEqual(obj.c, 4);
});

test('is exposed as a named property for interop', function () {
  assert.strictEqual(setPrototypeOf.setPrototypeOf, setPrototypeOf);
});

test('rejects non-object targets', function () {
  assert.throws(function () { setPrototypeOf(null, {}); }, TypeError);
  assert.throws(function () { setPrototypeOf(1, {}); }, TypeError);
});

test('rejects invalid prototypes', function () {
  assert.throws(function () { setPrototypeOf({}, 1); }, TypeError);
  assert.throws(function () { setPrototypeOf({}, 'x'); }, TypeError);
  assert.doesNotThrow(function () { setPrototypeOf({}, null); });
});

